import{_ as e,o as s,c as a,ag as i}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse('{"title":"UI Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/ui-settings.md","filePath":"configuration/ui-settings.md","lastUpdated":1772297611000}'),n={name:"configuration/ui-settings.md"};function o(r,t,h,l,d,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="ui-settings" tabindex="-1">UI Settings <a class="header-anchor" href="#ui-settings" aria-label="Permalink to &quot;UI Settings&quot;">​</a></h1><p>NectoProxy&#39;s Web UI is designed to be comfortable for extended debugging sessions. This page covers the appearance settings you can customize.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>NectoProxy supports three theme modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Dark</strong></td><td>A dark color scheme optimized for low-light environments and prolonged use. Uses dark gray backgrounds with light text.</td></tr><tr><td><strong>Light</strong></td><td>A light color scheme with white backgrounds and dark text, suitable for bright environments.</td></tr><tr><td><strong>System</strong></td><td>Automatically follows your operating system&#39;s appearance preference. If your OS switches between light and dark mode, NectoProxy switches with it.</td></tr></tbody></table><h3 id="default-theme" tabindex="-1">Default Theme <a class="header-anchor" href="#default-theme" aria-label="Permalink to &quot;Default Theme&quot;">​</a></h3><p>The default theme is <strong>dark</strong>. On first launch, NectoProxy renders in dark mode unless you change the setting.</p><h3 id="changing-the-theme" tabindex="-1">Changing the Theme <a class="header-anchor" href="#changing-the-theme" aria-label="Permalink to &quot;Changing the Theme&quot;">​</a></h3><p>There are two ways to change the theme:</p><h4 id="_1-header-toggle-button" tabindex="-1">1. Header Toggle Button <a class="header-anchor" href="#_1-header-toggle-button" aria-label="Permalink to &quot;1. Header Toggle Button&quot;">​</a></h4><p>The quickest way to switch themes is the <strong>sun/moon toggle button</strong> in the top-right area of the header toolbar:</p><ul><li>Click the <strong>Sun icon</strong> to switch to light mode.</li><li>Click the <strong>Moon icon</strong> to switch to dark mode.</li></ul><p>This button cycles between light and dark modes instantly.</p><h4 id="_2-settings-panel" tabindex="-1">2. Settings Panel <a class="header-anchor" href="#_2-settings-panel" aria-label="Permalink to &quot;2. Settings Panel&quot;">​</a></h4><p>For full control -- including the <strong>System</strong> option -- open the Settings panel (gear icon in the header) and scroll to the <strong>Appearance</strong> section:</p><ol><li>Click the <strong>gear icon</strong> in the header toolbar.</li><li>Scroll down to <strong>Appearance</strong>.</li><li>Select your preferred theme from the dropdown: <strong>Dark</strong>, <strong>Light</strong>, or <strong>System</strong>.</li><li>Click <strong>Save Changes</strong>.</li></ol><h3 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h3><p>Theme preference is stored in the browser&#39;s <code>localStorage</code>, so it persists across page reloads and browser sessions. Each browser profile maintains its own independent theme preference.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you use NectoProxy on multiple machines or browsers, you will need to set your theme preference in each one individually. The theme setting is local to the browser, not stored in the NectoProxy database.</p></div><h3 id="settings-api" tabindex="-1">Settings API <a class="header-anchor" href="#settings-api" aria-label="Permalink to &quot;Settings API&quot;">​</a></h3><p>You can also change the theme programmatically through the Settings API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set theme to light</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/theme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: &quot;light&quot;}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set theme to system</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8889/api/settings/theme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;value&quot;: &quot;system&quot;}&#39;</span></span></code></pre></div><details class="details custom-block"><summary>How Does &quot;System&quot; Mode Work?</summary><p>When set to <code>system</code>, NectoProxy uses the CSS <code>prefers-color-scheme</code> media query to detect your operating system&#39;s current theme. It registers a listener for changes, so if you switch your OS from light to dark mode (or vice versa) while NectoProxy is open, the UI updates in real time without a page refresh.</p></details><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Options</th><th>Persisted In</th><th>Scope</th></tr></thead><tbody><tr><td>Theme</td><td><code>dark</code></td><td><code>dark</code>, <code>light</code>, <code>system</code></td><td>Browser <code>localStorage</code></td><td>Per-browser</td></tr></tbody></table>`,25)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
